def _addon_s40_of14(datasources, start_date, end_date):
    """
    只在 14:30：截面前 10 分钟主动买卖失衡

    评分机批量筛选候选（s40）。共用分钟级统计 SQL（单次 GROUP BY，不用窗口函数），跨段运算在 pandas 中完成。
    最终：逐截面排名居中，09:30 截面置 0，缺失补 0。只用过去数据。
    """
    import numpy as np
    import pandas as pd
    import dai

    bar1m = datasources["bar1m"]
    LOOKBACK_DAYS = 10
    query_start = (pd.to_datetime(start_date) - pd.Timedelta(days=LOOKBACK_DAYS)).strftime("%Y-%m-%d %H:%M:%S")
    sql = f"""
    WITH cte_raw AS (
        SELECT
            instrument_id,
            strftime(date, '%Y-%m-%d') AS trading_day,
            strftime(date, '%H%M%S') AS hms,
            CAST(open AS DOUBLE) AS o, CAST(high AS DOUBLE) AS h, CAST(low AS DOUBLE) AS l, CAST(close AS DOUBLE) AS c,
            CAST(COALESCE(volume, 0) AS DOUBLE) AS v, CAST(COALESCE(amount, 0) AS DOUBLE) AS a,
            CAST(COALESCE(deal_number, 0) AS DOUBLE) AS nd, CAST(pre_close AS DOUBLE) AS pc,
            CAST(bid_price1 AS DOUBLE) AS b1, CAST(ask_price1 AS DOUBLE) AS a1,
            CAST(bid_price2 AS DOUBLE) AS b2, CAST(ask_price2 AS DOUBLE) AS a2,
            CAST(bid_price3 AS DOUBLE) AS b3, CAST(ask_price3 AS DOUBLE) AS a3,
            CAST(COALESCE(bid_volume1, 0) AS DOUBLE) AS bv1, CAST(COALESCE(ask_volume1, 0) AS DOUBLE) AS av1,
            CAST(COALESCE(bid_volume2, 0) + COALESCE(bid_volume3, 0) AS DOUBLE) AS bv23, CAST(COALESCE(ask_volume2, 0) + COALESCE(ask_volume3, 0) AS DOUBLE) AS av23,
            CAST(COALESCE(bid_num_orders1, 0) AS DOUBLE) AS bn1, CAST(COALESCE(ask_num_orders1, 0) AS DOUBLE) AS an1,
            CAST(COALESCE(bid_num_orders2, 0) AS DOUBLE) AS bn2, CAST(COALESCE(ask_num_orders2, 0) AS DOUBLE) AS an2,
            CAST(COALESCE(bid_num_orders3, 0) AS DOUBLE) AS bn3, CAST(COALESCE(ask_num_orders3, 0) AS DOUBLE) AS an3
        FROM {bar1m}
    ),
    cte_m AS (
        SELECT
            instrument_id, trading_day, hms, o, h, l, c, v, a, nd, pc, b1, a1, bv1, bv23, av1, av23,
            CASE WHEN (bn1) + (an1) > 0 THEN ((bn1) - (an1)) / ((bn1) + (an1)) ELSE NULL END AS qn1,
            CASE WHEN (bn2) + (an2) > 0 THEN ((bn2) - (an2)) / ((bn2) + (an2)) ELSE NULL END AS qn2,
            CASE WHEN (bn3) + (an3) > 0 THEN ((bn3) - (an3)) / ((bn3) + (an3)) ELSE NULL END AS qn3,
            CASE WHEN (bn2 + bn3) + (an2 + an3) > 0 THEN ((bn2 + bn3) - (an2 + an3)) / ((bn2 + bn3) + (an2 + an3)) ELSE NULL END AS qn23,
            CASE WHEN (bv1) + (av1) > 0 THEN ((bv1) - (av1)) / ((bv1) + (av1)) ELSE NULL END AS qv1,
            CASE WHEN (bv23) + (av23) > 0 THEN ((bv23) - (av23)) / ((bv23) + (av23)) ELSE NULL END AS qv23,
            CASE WHEN bn1 > 0 AND an1 > 0 AND bv1 > 0 AND av1 > 0 THEN ln((bv1 / bn1) / (av1 / an1)) ELSE NULL END AS qs1,
            CASE WHEN bn2 + bn3 > 0 AND an2 + an3 > 0 AND bv23 > 0 AND av23 > 0 THEN ln((bv23 / (bn2 + bn3)) / (av23 / (an2 + an3))) ELSE NULL END AS qs23,
            CASE WHEN bv1 > 0 AND av1 > 0 AND bv23 > 0 AND av23 > 0 THEN ln(bv23 / bv1) - ln(av23 / av1) ELSE NULL END AS qth,
            CASE WHEN hms > '090000' AND hms <= '093000' THEN '093000' WHEN hms > '093000' AND hms <= '100000' THEN '100000'
                 WHEN hms > '100000' AND hms <= '103000' THEN '103000' WHEN hms > '103000' AND hms <= '110000' THEN '110000'
                 WHEN hms > '110000' AND hms <= '113000' THEN '113000' WHEN hms > '130000' AND hms <= '133000' THEN '133000'
                 WHEN hms > '133000' AND hms <= '140000' THEN '140000' WHEN hms > '140000' AND hms <= '143000' THEN '143000'
                 ELSE '150000' END AS seg_end_s,
            CASE
                WHEN hms > '090000' AND hms <= '093000' THEN 93000
                WHEN hms > '093000' AND hms <= '100000' THEN 100000
                WHEN hms > '100000' AND hms <= '103000' THEN 103000
                WHEN hms > '103000' AND hms <= '110000' THEN 110000
                WHEN hms > '110000' AND hms <= '113000' THEN 113000
                WHEN hms > '130000' AND hms <= '133000' THEN 133000
                WHEN hms > '133000' AND hms <= '140000' THEN 140000
                WHEN hms > '140000' AND hms <= '143000' THEN 143000
                WHEN hms > '143000' AND hms <= '150000' THEN 150000
                ELSE -1
            END AS seg,
            CASE WHEN o > 0 AND c > 0 AND v > 0 THEN ln(c / o) ELSE NULL END AS r,
            CASE WHEN h > l AND v > 0 AND o > 0 AND c > 0 THEN v * (c - o) / (h - l) ELSE 0 END AS sv,
            CASE WHEN b1 > 0 AND a1 > b1 THEN (a1 + b1) / 2.0 ELSE NULL END AS mid,
            CASE WHEN b1 > 0 AND a1 > b1 AND c > 0 THEN LEAST(GREATEST((c - b1) / (a1 - b1), 0.0), 1.0) ELSE NULL END AS tpos,
            CASE WHEN b1 > 0 AND a1 > b1 AND a2 > a1 AND b2 > 0 AND b2 < b1 THEN ((a2 - a1) - (b1 - b2)) / ((a1 + b1) / 2.0) ELSE NULL END AS gap12,
            CASE WHEN b1 > 0 AND a1 > b1 AND a3 > a1 AND b3 > 0 AND b3 < b1 THEN ((a3 - a1) - (b1 - b3)) / ((a1 + b1) / 2.0) ELSE NULL END AS gap13
        FROM cte_raw
    ),
    cte_seg AS (
        SELECT
            trading_day, seg, instrument_id,
            SUM(r) AS sr, SUM(r * r) AS sr2, SUM(r * r * r) AS sr3, SUM(r * r * r * r) AS sr4, SUM(ABS(r)) AS sabs,
            SUM(CASE WHEN r > 0 THEN r * r ELSE 0 END) AS sr2p, SUM(CASE WHEN r < 0 THEN r * r ELSE 0 END) AS sr2n,
            MAX(r) AS rmax, MIN(r) AS rmin, COUNT(r) AS nmin, SUM(CASE WHEN r = 0 THEN 1 ELSE 0 END) AS nzero,
            SUM(sv) AS ssv, SUM(COALESCE(r, 0) * sv) AS srsv, SUM(sv * sv) AS ssv2,
            SUM(CASE WHEN sv > 0 THEN COALESCE(r, 0) * sv ELSE 0 END) AS srsvp, SUM(CASE WHEN sv > 0 THEN sv * sv ELSE 0 END) AS ssv2p,
            SUM(CASE WHEN sv < 0 THEN COALESCE(r, 0) * sv ELSE 0 END) AS srsvn, SUM(CASE WHEN sv < 0 THEN sv * sv ELSE 0 END) AS ssv2n,
            SUM(CASE WHEN r > 0 THEN v ELSE 0 END) AS vup, SUM(CASE WHEN r < 0 THEN v ELSE 0 END) AS vdn,
            SUM(v) AS vol, SUM(a) AS amt, SUM(nd) AS ndeal,
            AVG(tpos) AS tpos, AVG(gap12) AS gap12, AVG(gap13) AS gap13,
            arg_min(CASE WHEN o > 0 THEN o ELSE NULL END, hms) AS s_open, MAX(CASE WHEN h > 0 THEN h ELSE NULL END) AS s_high,
            MIN(CASE WHEN l > 0 THEN l ELSE NULL END) AS s_low,
            arg_max(CASE WHEN mid > 0 THEN mid WHEN c > 0 THEN c ELSE NULL END, hms) AS last_px,
            arg_max(hms, CASE WHEN h > 0 THEN h ELSE NULL END) AS hms_high, arg_min(hms, CASE WHEN l > 0 THEN l ELSE NULL END) AS hms_low,
            MAX(pc) AS pre_close
            , AVG(qn1) AS qn1, AVG(qn2) AS qn2, AVG(qn3) AS qn3, AVG(qn23) AS qn23, AVG(qv1) AS qv1, AVG(qv23) AS qv23,
            AVG(qs1) AS qs1, AVG(qs23) AS qs23, AVG(qth) AS qth,
            AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') THEN qn23 END) AS qn23L,
            AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') THEN qs1 END) AS qs1L,
            arg_max(qn23, hms) AS qn23E, arg_max(qs1, hms) AS qs1E,
            arg_min(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 5 MINUTE, '%H%M%S') THEN COALESCE(mid, c) END, CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 5 MINUTE, '%H%M%S') THEN hms END) AS p_l5,
            arg_min(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') THEN COALESCE(mid, c) END, CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') THEN hms END) AS p_l10,
            SUM(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 5 MINUTE, '%H%M%S') THEN v ELSE 0 END) AS v_l5,
            AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 5 MINUTE, '%H%M%S') AND bv1 + bv23 + av1 + av23 > 0 THEN (bv1 + bv23 - av1 - av23) / (bv1 + bv23 + av1 + av23) END) AS dimb_l5,
            AVG(CASE WHEN bv1 + bv23 + av1 + av23 > 0 THEN (bv1 + bv23 - av1 - av23) / (bv1 + bv23 + av1 + av23) END) AS dimb_all,
            AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 5 MINUTE, '%H%M%S') AND b1 > 0 AND a1 > b1 THEN (a1 - b1) / ((a1 + b1) / 2.0) END) AS spr_l5,
            AVG(CASE WHEN b1 > 0 AND a1 > b1 THEN (a1 - b1) / ((a1 + b1) / 2.0) END) AS spr_all,
            MAX(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') AND c > 0 THEN c END) AS hi_l10, MIN(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') AND c > 0 THEN c END) AS lo_l10
            , SUM(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') THEN v * (1 - COALESCE(tpos, 0.5)) ELSE 0 END) AS vs_l,
            SUM(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') THEN v * COALESCE(tpos, 0.5) ELSE 0 END) AS vb_l
        FROM cte_m
        WHERE seg != -1
        GROUP BY instrument_id, trading_day, seg
    )
    SELECT
        CAST(CONCAT(f.trading_day, ' ', strftime(strptime(LPAD(CAST(f.seg AS VARCHAR), 6, '0'), '%H%M%S'), '%H:%M:%S')) AS DATETIME) AS date,
        all_instruments.instrument, f.*
    FROM cte_seg f
    LEFT JOIN all_instruments USING (instrument_id)
"""
    df = dai.query(sql, filters={"date": [query_start, end_date]}, compression=True).df()
    df = df.dropna(subset=["instrument"]).drop_duplicates(["date", "instrument"])
    df["date"] = pd.to_datetime(df["date"])
    for c in df.columns:
        if c not in ("date", "instrument", "trading_day", "seg", "instrument_id", "hms_high", "hms_low"):
            df[c] = df[c].astype("float64")
    df = df.sort_values(["instrument", "date"]).reset_index(drop=True)
    df["day"] = df["date"].dt.normalize()
    inst = df["instrument"]
    g = df.groupby("instrument", sort=False)
    gd = df.groupby(["instrument", "day"], sort=False)

    def pos(x):
        return x.where(x > 0)

    def lr(a, b):
        return np.log(pos(a) / pos(b))

    def roll(col, k):
        x = df[col].fillna(0.0) if isinstance(col, str) else col.fillna(0.0)
        cs = x.groupby(inst).cumsum()
        return cs - cs.groupby(inst).shift(k).fillna(0.0)

    def tmin(hms):
        """时刻 → 开盘以来的交易分钟（午休不计）。"""
        t = pd.to_numeric(hms, errors="coerce")
        hh, mm = t // 10000, (t // 100) % 100
        m = hh * 60 + mm
        return np.where(m <= 690, m - 570, m - 660)

    px = pos(df["last_px"])
    prev = g["last_px"].shift(1)
    r_seg = lr(px, prev)
    day_open = gd["s_open"].transform("first")
    day_high = gd["s_high"].cummax()
    day_low = gd["s_low"].cummin()
    newh = df["s_high"] >= day_high
    newl = df["s_low"] <= day_low
    t_high = pd.Series(np.where(newh, tmin(df["hms_high"]), np.nan), index=df.index).groupby([inst, df["day"]]).ffill()
    t_low = pd.Series(np.where(newl, tmin(df["hms_low"]), np.nan), index=df.index).groupby([inst, df["day"]]).ffill()
    t_now = pd.Series(tmin(df["date"].dt.strftime("%H%M%S")), index=df.index)

    hm_ = df['date'].dt.hour * 100 + df['date'].dt.minute
    x = ((df['vb_l'] - df['vs_l']) / pos(df['vb_l'] + df['vs_l'])).where(hm_ == 1430)

    x = pd.Series(np.asarray(x, dtype="float64"), index=df.index).replace([np.inf, -np.inf], np.nan)
    df["x"] = x
    instruments_table = datasources.get("instruments", "cpt_jyc_2026_instruments")
    pool = dai.query(f"SELECT date, instrument FROM {instruments_table}", filters={"date": [query_start, end_date]}, compression=True).df()
    pool["date"] = pd.to_datetime(pool["date"])
    res = pd.merge(pool, df[["date", "instrument", "x"]], how="left", on=["date", "instrument"]).drop_duplicates(["date", "instrument"])
    res["factor"] = res.groupby("date")["x"].rank(pct=True) - 0.5
    res["factor"] = res["factor"].fillna(0.0)
    hhmm = res["date"].dt.hour * 100 + res["date"].dt.minute
    res.loc[hhmm == 930, "factor"] = 0.0
    SMOOTH = 0.0
    if SMOOTH > 0:
        res = res.sort_values(["instrument", "date"])
        res["factor"] = res.groupby("instrument", sort=False)["factor"].transform(lambda q: q.ewm(alpha=1.0 - SMOOTH, adjust=False).mean())
        res.loc[hhmm.loc[res.index] == 930, "factor"] = 0.0
    res = res[(res["date"] >= pd.to_datetime(start_date)) & (res["date"] <= pd.to_datetime(end_date))]
    res["factor"] = res["factor"].replace([np.inf, -np.inf], np.nan).astype("float64").fillna(0.0)
    return res[["date", "instrument", "factor"]].sort_values(["date", "instrument"]).reset_index(drop=True)


def _addon_s40_q14_end(datasources, start_date, end_date):
    """
    只在 14:30：段末快照深档笔数失衡 + 一档规模比取负（各自排名）

    评分机批量筛选候选（s40）。共用分钟级统计 SQL（单次 GROUP BY，不用窗口函数），跨段运算在 pandas 中完成。
    最终：逐截面排名居中，09:30 截面置 0，缺失补 0。只用过去数据。
    """
    import numpy as np
    import pandas as pd
    import dai

    bar1m = datasources["bar1m"]
    LOOKBACK_DAYS = 10
    query_start = (pd.to_datetime(start_date) - pd.Timedelta(days=LOOKBACK_DAYS)).strftime("%Y-%m-%d %H:%M:%S")
    sql = f"""
    WITH cte_raw AS (
        SELECT
            instrument_id,
            strftime(date, '%Y-%m-%d') AS trading_day,
            strftime(date, '%H%M%S') AS hms,
            CAST(open AS DOUBLE) AS o, CAST(high AS DOUBLE) AS h, CAST(low AS DOUBLE) AS l, CAST(close AS DOUBLE) AS c,
            CAST(COALESCE(volume, 0) AS DOUBLE) AS v, CAST(COALESCE(amount, 0) AS DOUBLE) AS a,
            CAST(COALESCE(deal_number, 0) AS DOUBLE) AS nd, CAST(pre_close AS DOUBLE) AS pc,
            CAST(bid_price1 AS DOUBLE) AS b1, CAST(ask_price1 AS DOUBLE) AS a1,
            CAST(bid_price2 AS DOUBLE) AS b2, CAST(ask_price2 AS DOUBLE) AS a2,
            CAST(bid_price3 AS DOUBLE) AS b3, CAST(ask_price3 AS DOUBLE) AS a3,
            CAST(COALESCE(bid_volume1, 0) AS DOUBLE) AS bv1, CAST(COALESCE(ask_volume1, 0) AS DOUBLE) AS av1,
            CAST(COALESCE(bid_volume2, 0) + COALESCE(bid_volume3, 0) AS DOUBLE) AS bv23, CAST(COALESCE(ask_volume2, 0) + COALESCE(ask_volume3, 0) AS DOUBLE) AS av23,
            CAST(COALESCE(bid_num_orders1, 0) AS DOUBLE) AS bn1, CAST(COALESCE(ask_num_orders1, 0) AS DOUBLE) AS an1,
            CAST(COALESCE(bid_num_orders2, 0) AS DOUBLE) AS bn2, CAST(COALESCE(ask_num_orders2, 0) AS DOUBLE) AS an2,
            CAST(COALESCE(bid_num_orders3, 0) AS DOUBLE) AS bn3, CAST(COALESCE(ask_num_orders3, 0) AS DOUBLE) AS an3
        FROM {bar1m}
    ),
    cte_m AS (
        SELECT
            instrument_id, trading_day, hms, o, h, l, c, v, a, nd, pc,
            CASE WHEN (bn1) + (an1) > 0 THEN ((bn1) - (an1)) / ((bn1) + (an1)) ELSE NULL END AS qn1,
            CASE WHEN (bn2) + (an2) > 0 THEN ((bn2) - (an2)) / ((bn2) + (an2)) ELSE NULL END AS qn2,
            CASE WHEN (bn3) + (an3) > 0 THEN ((bn3) - (an3)) / ((bn3) + (an3)) ELSE NULL END AS qn3,
            CASE WHEN (bn2 + bn3) + (an2 + an3) > 0 THEN ((bn2 + bn3) - (an2 + an3)) / ((bn2 + bn3) + (an2 + an3)) ELSE NULL END AS qn23,
            CASE WHEN (bv1) + (av1) > 0 THEN ((bv1) - (av1)) / ((bv1) + (av1)) ELSE NULL END AS qv1,
            CASE WHEN (bv23) + (av23) > 0 THEN ((bv23) - (av23)) / ((bv23) + (av23)) ELSE NULL END AS qv23,
            CASE WHEN bn1 > 0 AND an1 > 0 AND bv1 > 0 AND av1 > 0 THEN ln((bv1 / bn1) / (av1 / an1)) ELSE NULL END AS qs1,
            CASE WHEN bn2 + bn3 > 0 AND an2 + an3 > 0 AND bv23 > 0 AND av23 > 0 THEN ln((bv23 / (bn2 + bn3)) / (av23 / (an2 + an3))) ELSE NULL END AS qs23,
            CASE WHEN bv1 > 0 AND av1 > 0 AND bv23 > 0 AND av23 > 0 THEN ln(bv23 / bv1) - ln(av23 / av1) ELSE NULL END AS qth,
            CASE WHEN hms > '090000' AND hms <= '093000' THEN '093000' WHEN hms > '093000' AND hms <= '100000' THEN '100000'
                 WHEN hms > '100000' AND hms <= '103000' THEN '103000' WHEN hms > '103000' AND hms <= '110000' THEN '110000'
                 WHEN hms > '110000' AND hms <= '113000' THEN '113000' WHEN hms > '130000' AND hms <= '133000' THEN '133000'
                 WHEN hms > '133000' AND hms <= '140000' THEN '140000' WHEN hms > '140000' AND hms <= '143000' THEN '143000'
                 ELSE '150000' END AS seg_end_s,
            CASE
                WHEN hms > '090000' AND hms <= '093000' THEN 93000
                WHEN hms > '093000' AND hms <= '100000' THEN 100000
                WHEN hms > '100000' AND hms <= '103000' THEN 103000
                WHEN hms > '103000' AND hms <= '110000' THEN 110000
                WHEN hms > '110000' AND hms <= '113000' THEN 113000
                WHEN hms > '130000' AND hms <= '133000' THEN 133000
                WHEN hms > '133000' AND hms <= '140000' THEN 140000
                WHEN hms > '140000' AND hms <= '143000' THEN 143000
                WHEN hms > '143000' AND hms <= '150000' THEN 150000
                ELSE -1
            END AS seg,
            CASE WHEN o > 0 AND c > 0 AND v > 0 THEN ln(c / o) ELSE NULL END AS r,
            CASE WHEN h > l AND v > 0 AND o > 0 AND c > 0 THEN v * (c - o) / (h - l) ELSE 0 END AS sv,
            CASE WHEN b1 > 0 AND a1 > b1 THEN (a1 + b1) / 2.0 ELSE NULL END AS mid,
            CASE WHEN b1 > 0 AND a1 > b1 AND c > 0 THEN LEAST(GREATEST((c - b1) / (a1 - b1), 0.0), 1.0) ELSE NULL END AS tpos,
            CASE WHEN b1 > 0 AND a1 > b1 AND a2 > a1 AND b2 > 0 AND b2 < b1 THEN ((a2 - a1) - (b1 - b2)) / ((a1 + b1) / 2.0) ELSE NULL END AS gap12,
            CASE WHEN b1 > 0 AND a1 > b1 AND a3 > a1 AND b3 > 0 AND b3 < b1 THEN ((a3 - a1) - (b1 - b3)) / ((a1 + b1) / 2.0) ELSE NULL END AS gap13
        FROM cte_raw
    ),
    cte_seg AS (
        SELECT
            trading_day, seg, instrument_id,
            SUM(r) AS sr, SUM(r * r) AS sr2, SUM(r * r * r) AS sr3, SUM(r * r * r * r) AS sr4, SUM(ABS(r)) AS sabs,
            SUM(CASE WHEN r > 0 THEN r * r ELSE 0 END) AS sr2p, SUM(CASE WHEN r < 0 THEN r * r ELSE 0 END) AS sr2n,
            MAX(r) AS rmax, MIN(r) AS rmin, COUNT(r) AS nmin, SUM(CASE WHEN r = 0 THEN 1 ELSE 0 END) AS nzero,
            SUM(sv) AS ssv, SUM(COALESCE(r, 0) * sv) AS srsv, SUM(sv * sv) AS ssv2,
            SUM(CASE WHEN sv > 0 THEN COALESCE(r, 0) * sv ELSE 0 END) AS srsvp, SUM(CASE WHEN sv > 0 THEN sv * sv ELSE 0 END) AS ssv2p,
            SUM(CASE WHEN sv < 0 THEN COALESCE(r, 0) * sv ELSE 0 END) AS srsvn, SUM(CASE WHEN sv < 0 THEN sv * sv ELSE 0 END) AS ssv2n,
            SUM(CASE WHEN r > 0 THEN v ELSE 0 END) AS vup, SUM(CASE WHEN r < 0 THEN v ELSE 0 END) AS vdn,
            SUM(v) AS vol, SUM(a) AS amt, SUM(nd) AS ndeal,
            AVG(tpos) AS tpos, AVG(gap12) AS gap12, AVG(gap13) AS gap13,
            arg_min(CASE WHEN o > 0 THEN o ELSE NULL END, hms) AS s_open, MAX(CASE WHEN h > 0 THEN h ELSE NULL END) AS s_high,
            MIN(CASE WHEN l > 0 THEN l ELSE NULL END) AS s_low,
            arg_max(CASE WHEN mid > 0 THEN mid WHEN c > 0 THEN c ELSE NULL END, hms) AS last_px,
            arg_max(hms, CASE WHEN h > 0 THEN h ELSE NULL END) AS hms_high, arg_min(hms, CASE WHEN l > 0 THEN l ELSE NULL END) AS hms_low,
            MAX(pc) AS pre_close
            , AVG(qn1) AS qn1, AVG(qn2) AS qn2, AVG(qn3) AS qn3, AVG(qn23) AS qn23, AVG(qv1) AS qv1, AVG(qv23) AS qv23,
            AVG(qs1) AS qs1, AVG(qs23) AS qs23, AVG(qth) AS qth,
            AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') THEN qn23 END) AS qn23L,
            AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') THEN qs1 END) AS qs1L,
            arg_max(qn23, hms) AS qn23E, arg_max(qs1, hms) AS qs1E,
            AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 5 MINUTE, '%H%M%S') THEN qn23 END) AS qn23L5, AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 5 MINUTE, '%H%M%S') THEN qs1 END) AS qs1L5,
            AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 15 MINUTE, '%H%M%S') THEN qn23 END) AS qn23L15, AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 15 MINUTE, '%H%M%S') THEN qs1 END) AS qs1L15,
            AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') THEN qn1 END) AS qn1L, AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') THEN qv23 END) AS qv23L
        FROM cte_m
        WHERE seg != -1
        GROUP BY instrument_id, trading_day, seg
    )
    SELECT
        CAST(CONCAT(f.trading_day, ' ', strftime(strptime(LPAD(CAST(f.seg AS VARCHAR), 6, '0'), '%H%M%S'), '%H:%M:%S')) AS DATETIME) AS date,
        all_instruments.instrument, f.*
    FROM cte_seg f
    LEFT JOIN all_instruments USING (instrument_id)
"""
    df = dai.query(sql, filters={"date": [query_start, end_date]}, compression=True).df()
    df = df.dropna(subset=["instrument"]).drop_duplicates(["date", "instrument"])
    df["date"] = pd.to_datetime(df["date"])
    for c in df.columns:
        if c not in ("date", "instrument", "trading_day", "seg", "instrument_id", "hms_high", "hms_low"):
            df[c] = df[c].astype("float64")
    df = df.sort_values(["instrument", "date"]).reset_index(drop=True)
    df["day"] = df["date"].dt.normalize()
    inst = df["instrument"]
    g = df.groupby("instrument", sort=False)
    gd = df.groupby(["instrument", "day"], sort=False)

    def pos(x):
        return x.where(x > 0)

    def lr(a, b):
        return np.log(pos(a) / pos(b))

    def roll(col, k):
        x = df[col].fillna(0.0) if isinstance(col, str) else col.fillna(0.0)
        cs = x.groupby(inst).cumsum()
        return cs - cs.groupby(inst).shift(k).fillna(0.0)

    def tmin(hms):
        """时刻 → 开盘以来的交易分钟（午休不计）。"""
        t = pd.to_numeric(hms, errors="coerce")
        hh, mm = t // 10000, (t // 100) % 100
        m = hh * 60 + mm
        return np.where(m <= 690, m - 570, m - 660)

    px = pos(df["last_px"])
    prev = g["last_px"].shift(1)
    r_seg = lr(px, prev)
    day_open = gd["s_open"].transform("first")
    day_high = gd["s_high"].cummax()
    day_low = gd["s_low"].cummin()
    newh = df["s_high"] >= day_high
    newl = df["s_low"] <= day_low
    t_high = pd.Series(np.where(newh, tmin(df["hms_high"]), np.nan), index=df.index).groupby([inst, df["day"]]).ffill()
    t_low = pd.Series(np.where(newl, tmin(df["hms_low"]), np.nan), index=df.index).groupby([inst, df["day"]]).ffill()
    t_now = pd.Series(tmin(df["date"].dt.strftime("%H%M%S")), index=df.index)

    hm_ = df['date'].dt.hour * 100 + df['date'].dt.minute
    rk = lambda v: pd.Series(np.asarray(v, dtype='float64'), index=df.index).groupby(df['date']).rank(pct=True)
    x = (rk(df['qn23E']).fillna(0.5) + rk(-df['qs1E']).fillna(0.5)).where(hm_ == 1430)

    x = pd.Series(np.asarray(x, dtype="float64"), index=df.index).replace([np.inf, -np.inf], np.nan)
    df["x"] = x
    instruments_table = datasources.get("instruments", "cpt_jyc_2026_instruments")
    pool = dai.query(f"SELECT date, instrument FROM {instruments_table}", filters={"date": [query_start, end_date]}, compression=True).df()
    pool["date"] = pd.to_datetime(pool["date"])
    res = pd.merge(pool, df[["date", "instrument", "x"]], how="left", on=["date", "instrument"]).drop_duplicates(["date", "instrument"])
    res["factor"] = res.groupby("date")["x"].rank(pct=True) - 0.5
    res["factor"] = res["factor"].fillna(0.0)
    hhmm = res["date"].dt.hour * 100 + res["date"].dt.minute
    res.loc[hhmm == 930, "factor"] = 0.0
    SMOOTH = 0.0
    if SMOOTH > 0:
        res = res.sort_values(["instrument", "date"])
        res["factor"] = res.groupby("instrument", sort=False)["factor"].transform(lambda q: q.ewm(alpha=1.0 - SMOOTH, adjust=False).mean())
        res.loc[hhmm.loc[res.index] == 930, "factor"] = 0.0
    res = res[(res["date"] >= pd.to_datetime(start_date)) & (res["date"] <= pd.to_datetime(end_date))]
    res["factor"] = res["factor"].replace([np.inf, -np.inf], np.nan).astype("float64").fillna(0.0)
    return res[["date", "instrument", "factor"]].sort_values(["date", "instrument"]).reset_index(drop=True)


def _addon_s40_q14_s1(datasources, start_date, end_date):
    """
    只在 14:30：一档委托规模比取负（截面前 10 分钟）

    评分机批量筛选候选（s40）。共用分钟级统计 SQL（单次 GROUP BY，不用窗口函数），跨段运算在 pandas 中完成。
    最终：逐截面排名居中，09:30 截面置 0，缺失补 0。只用过去数据。
    """
    import numpy as np
    import pandas as pd
    import dai

    bar1m = datasources["bar1m"]
    LOOKBACK_DAYS = 10
    query_start = (pd.to_datetime(start_date) - pd.Timedelta(days=LOOKBACK_DAYS)).strftime("%Y-%m-%d %H:%M:%S")
    sql = f"""
    WITH cte_raw AS (
        SELECT
            instrument_id,
            strftime(date, '%Y-%m-%d') AS trading_day,
            strftime(date, '%H%M%S') AS hms,
            CAST(open AS DOUBLE) AS o, CAST(high AS DOUBLE) AS h, CAST(low AS DOUBLE) AS l, CAST(close AS DOUBLE) AS c,
            CAST(COALESCE(volume, 0) AS DOUBLE) AS v, CAST(COALESCE(amount, 0) AS DOUBLE) AS a,
            CAST(COALESCE(deal_number, 0) AS DOUBLE) AS nd, CAST(pre_close AS DOUBLE) AS pc,
            CAST(bid_price1 AS DOUBLE) AS b1, CAST(ask_price1 AS DOUBLE) AS a1,
            CAST(bid_price2 AS DOUBLE) AS b2, CAST(ask_price2 AS DOUBLE) AS a2,
            CAST(bid_price3 AS DOUBLE) AS b3, CAST(ask_price3 AS DOUBLE) AS a3,
            CAST(COALESCE(bid_volume1, 0) AS DOUBLE) AS bv1, CAST(COALESCE(ask_volume1, 0) AS DOUBLE) AS av1,
            CAST(COALESCE(bid_volume2, 0) + COALESCE(bid_volume3, 0) AS DOUBLE) AS bv23, CAST(COALESCE(ask_volume2, 0) + COALESCE(ask_volume3, 0) AS DOUBLE) AS av23,
            CAST(COALESCE(bid_num_orders1, 0) AS DOUBLE) AS bn1, CAST(COALESCE(ask_num_orders1, 0) AS DOUBLE) AS an1,
            CAST(COALESCE(bid_num_orders2, 0) AS DOUBLE) AS bn2, CAST(COALESCE(ask_num_orders2, 0) AS DOUBLE) AS an2,
            CAST(COALESCE(bid_num_orders3, 0) AS DOUBLE) AS bn3, CAST(COALESCE(ask_num_orders3, 0) AS DOUBLE) AS an3
        FROM {bar1m}
    ),
    cte_m AS (
        SELECT
            instrument_id, trading_day, hms, o, h, l, c, v, a, nd, pc,
            CASE WHEN (bn1) + (an1) > 0 THEN ((bn1) - (an1)) / ((bn1) + (an1)) ELSE NULL END AS qn1,
            CASE WHEN (bn2) + (an2) > 0 THEN ((bn2) - (an2)) / ((bn2) + (an2)) ELSE NULL END AS qn2,
            CASE WHEN (bn3) + (an3) > 0 THEN ((bn3) - (an3)) / ((bn3) + (an3)) ELSE NULL END AS qn3,
            CASE WHEN (bn2 + bn3) + (an2 + an3) > 0 THEN ((bn2 + bn3) - (an2 + an3)) / ((bn2 + bn3) + (an2 + an3)) ELSE NULL END AS qn23,
            CASE WHEN (bv1) + (av1) > 0 THEN ((bv1) - (av1)) / ((bv1) + (av1)) ELSE NULL END AS qv1,
            CASE WHEN (bv23) + (av23) > 0 THEN ((bv23) - (av23)) / ((bv23) + (av23)) ELSE NULL END AS qv23,
            CASE WHEN bn1 > 0 AND an1 > 0 AND bv1 > 0 AND av1 > 0 THEN ln((bv1 / bn1) / (av1 / an1)) ELSE NULL END AS qs1,
            CASE WHEN bn2 + bn3 > 0 AND an2 + an3 > 0 AND bv23 > 0 AND av23 > 0 THEN ln((bv23 / (bn2 + bn3)) / (av23 / (an2 + an3))) ELSE NULL END AS qs23,
            CASE WHEN bv1 > 0 AND av1 > 0 AND bv23 > 0 AND av23 > 0 THEN ln(bv23 / bv1) - ln(av23 / av1) ELSE NULL END AS qth,
            CASE WHEN bn1 > 0 AND bv1 > 0 THEN ln(bv1 / bn1) ELSE NULL END AS lbs1,
            CASE WHEN an1 > 0 AND av1 > 0 THEN ln(av1 / an1) ELSE NULL END AS las1,
            CASE WHEN hms > '090000' AND hms <= '093000' THEN '093000' WHEN hms > '093000' AND hms <= '100000' THEN '100000'
                 WHEN hms > '100000' AND hms <= '103000' THEN '103000' WHEN hms > '103000' AND hms <= '110000' THEN '110000'
                 WHEN hms > '110000' AND hms <= '113000' THEN '113000' WHEN hms > '130000' AND hms <= '133000' THEN '133000'
                 WHEN hms > '133000' AND hms <= '140000' THEN '140000' WHEN hms > '140000' AND hms <= '143000' THEN '143000'
                 ELSE '150000' END AS seg_end_s,
            CASE
                WHEN hms > '090000' AND hms <= '093000' THEN 93000
                WHEN hms > '093000' AND hms <= '100000' THEN 100000
                WHEN hms > '100000' AND hms <= '103000' THEN 103000
                WHEN hms > '103000' AND hms <= '110000' THEN 110000
                WHEN hms > '110000' AND hms <= '113000' THEN 113000
                WHEN hms > '130000' AND hms <= '133000' THEN 133000
                WHEN hms > '133000' AND hms <= '140000' THEN 140000
                WHEN hms > '140000' AND hms <= '143000' THEN 143000
                WHEN hms > '143000' AND hms <= '150000' THEN 150000
                ELSE -1
            END AS seg,
            CASE WHEN o > 0 AND c > 0 AND v > 0 THEN ln(c / o) ELSE NULL END AS r,
            CASE WHEN h > l AND v > 0 AND o > 0 AND c > 0 THEN v * (c - o) / (h - l) ELSE 0 END AS sv,
            CASE WHEN b1 > 0 AND a1 > b1 THEN (a1 + b1) / 2.0 ELSE NULL END AS mid,
            CASE WHEN b1 > 0 AND a1 > b1 AND c > 0 THEN LEAST(GREATEST((c - b1) / (a1 - b1), 0.0), 1.0) ELSE NULL END AS tpos,
            CASE WHEN b1 > 0 AND a1 > b1 AND a2 > a1 AND b2 > 0 AND b2 < b1 THEN ((a2 - a1) - (b1 - b2)) / ((a1 + b1) / 2.0) ELSE NULL END AS gap12,
            CASE WHEN b1 > 0 AND a1 > b1 AND a3 > a1 AND b3 > 0 AND b3 < b1 THEN ((a3 - a1) - (b1 - b3)) / ((a1 + b1) / 2.0) ELSE NULL END AS gap13
        FROM cte_raw
    ),
    cte_seg AS (
        SELECT
            trading_day, seg, instrument_id,
            SUM(r) AS sr, SUM(r * r) AS sr2, SUM(r * r * r) AS sr3, SUM(r * r * r * r) AS sr4, SUM(ABS(r)) AS sabs,
            SUM(CASE WHEN r > 0 THEN r * r ELSE 0 END) AS sr2p, SUM(CASE WHEN r < 0 THEN r * r ELSE 0 END) AS sr2n,
            MAX(r) AS rmax, MIN(r) AS rmin, COUNT(r) AS nmin, SUM(CASE WHEN r = 0 THEN 1 ELSE 0 END) AS nzero,
            SUM(sv) AS ssv, SUM(COALESCE(r, 0) * sv) AS srsv, SUM(sv * sv) AS ssv2,
            SUM(CASE WHEN sv > 0 THEN COALESCE(r, 0) * sv ELSE 0 END) AS srsvp, SUM(CASE WHEN sv > 0 THEN sv * sv ELSE 0 END) AS ssv2p,
            SUM(CASE WHEN sv < 0 THEN COALESCE(r, 0) * sv ELSE 0 END) AS srsvn, SUM(CASE WHEN sv < 0 THEN sv * sv ELSE 0 END) AS ssv2n,
            SUM(CASE WHEN r > 0 THEN v ELSE 0 END) AS vup, SUM(CASE WHEN r < 0 THEN v ELSE 0 END) AS vdn,
            SUM(v) AS vol, SUM(a) AS amt, SUM(nd) AS ndeal,
            AVG(tpos) AS tpos, AVG(gap12) AS gap12, AVG(gap13) AS gap13,
            arg_min(CASE WHEN o > 0 THEN o ELSE NULL END, hms) AS s_open, MAX(CASE WHEN h > 0 THEN h ELSE NULL END) AS s_high,
            MIN(CASE WHEN l > 0 THEN l ELSE NULL END) AS s_low,
            arg_max(CASE WHEN mid > 0 THEN mid WHEN c > 0 THEN c ELSE NULL END, hms) AS last_px,
            arg_max(hms, CASE WHEN h > 0 THEN h ELSE NULL END) AS hms_high, arg_min(hms, CASE WHEN l > 0 THEN l ELSE NULL END) AS hms_low,
            MAX(pc) AS pre_close
            , AVG(qn1) AS qn1, AVG(qn2) AS qn2, AVG(qn3) AS qn3, AVG(qn23) AS qn23, AVG(qv1) AS qv1, AVG(qv23) AS qv23,
            AVG(qs1) AS qs1, AVG(qs23) AS qs23, AVG(qth) AS qth,
            AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') THEN qn23 END) AS qn23L,
            AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') THEN qs1 END) AS qs1L,
            arg_max(qn23, hms) AS qn23E, arg_max(qs1, hms) AS qs1E,
            AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 5 MINUTE, '%H%M%S') THEN qn23 END) AS qn23L5, AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 5 MINUTE, '%H%M%S') THEN qs1 END) AS qs1L5,
            AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 15 MINUTE, '%H%M%S') THEN qn23 END) AS qn23L15, AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 15 MINUTE, '%H%M%S') THEN qs1 END) AS qs1L15,
            AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') THEN qn1 END) AS qn1L, AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') THEN qv23 END) AS qv23L,
            AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') THEN lbs1 END) AS lbs1L, AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') THEN las1 END) AS las1L, AVG(CASE WHEN hms > strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 10 MINUTE, '%H%M%S') THEN qs23 END) AS qs23L,
            AVG(CASE WHEN hms <= strftime(strptime(seg_end_s, '%H%M%S') - INTERVAL 20 MINUTE, '%H%M%S') THEN qs1 END) AS qs1F, AVG(lbs1) AS lbs1A, AVG(las1) AS las1A
        FROM cte_m
        WHERE seg != -1
        GROUP BY instrument_id, trading_day, seg
    )
    SELECT
        CAST(CONCAT(f.trading_day, ' ', strftime(strptime(LPAD(CAST(f.seg AS VARCHAR), 6, '0'), '%H%M%S'), '%H:%M:%S')) AS DATETIME) AS date,
        all_instruments.instrument, f.*
    FROM cte_seg f
    LEFT JOIN all_instruments USING (instrument_id)
"""
    df = dai.query(sql, filters={"date": [query_start, end_date]}, compression=True).df()
    df = df.dropna(subset=["instrument"]).drop_duplicates(["date", "instrument"])
    df["date"] = pd.to_datetime(df["date"])
    for c in df.columns:
        if c not in ("date", "instrument", "trading_day", "seg", "instrument_id", "hms_high", "hms_low"):
            df[c] = df[c].astype("float64")
    df = df.sort_values(["instrument", "date"]).reset_index(drop=True)
    df["day"] = df["date"].dt.normalize()
    inst = df["instrument"]
    g = df.groupby("instrument", sort=False)
    gd = df.groupby(["instrument", "day"], sort=False)

    def pos(x):
        return x.where(x > 0)

    def lr(a, b):
        return np.log(pos(a) / pos(b))

    def roll(col, k):
        x = df[col].fillna(0.0) if isinstance(col, str) else col.fillna(0.0)
        cs = x.groupby(inst).cumsum()
        return cs - cs.groupby(inst).shift(k).fillna(0.0)

    def tmin(hms):
        """时刻 → 开盘以来的交易分钟（午休不计）。"""
        t = pd.to_numeric(hms, errors="coerce")
        hh, mm = t // 10000, (t // 100) % 100
        m = hh * 60 + mm
        return np.where(m <= 690, m - 570, m - 660)

    px = pos(df["last_px"])
    prev = g["last_px"].shift(1)
    r_seg = lr(px, prev)
    day_open = gd["s_open"].transform("first")
    day_high = gd["s_high"].cummax()
    day_low = gd["s_low"].cummin()
    newh = df["s_high"] >= day_high
    newl = df["s_low"] <= day_low
    t_high = pd.Series(np.where(newh, tmin(df["hms_high"]), np.nan), index=df.index).groupby([inst, df["day"]]).ffill()
    t_low = pd.Series(np.where(newl, tmin(df["hms_low"]), np.nan), index=df.index).groupby([inst, df["day"]]).ffill()
    t_now = pd.Series(tmin(df["date"].dt.strftime("%H%M%S")), index=df.index)

    hm_ = df['date'].dt.hour * 100 + df['date'].dt.minute
    x = (-df['qs1L']).where(hm_ == 1430)

    x = pd.Series(np.asarray(x, dtype="float64"), index=df.index).replace([np.inf, -np.inf], np.nan)
    df["x"] = x
    instruments_table = datasources.get("instruments", "cpt_jyc_2026_instruments")
    pool = dai.query(f"SELECT date, instrument FROM {instruments_table}", filters={"date": [query_start, end_date]}, compression=True).df()
    pool["date"] = pd.to_datetime(pool["date"])
    res = pd.merge(pool, df[["date", "instrument", "x"]], how="left", on=["date", "instrument"]).drop_duplicates(["date", "instrument"])
    res["factor"] = res.groupby("date")["x"].rank(pct=True) - 0.5
    res["factor"] = res["factor"].fillna(0.0)
    hhmm = res["date"].dt.hour * 100 + res["date"].dt.minute
    res.loc[hhmm == 930, "factor"] = 0.0
    SMOOTH = 0.0
    if SMOOTH > 0:
        res = res.sort_values(["instrument", "date"])
        res["factor"] = res.groupby("instrument", sort=False)["factor"].transform(lambda q: q.ewm(alpha=1.0 - SMOOTH, adjust=False).mean())
        res.loc[hhmm.loc[res.index] == 930, "factor"] = 0.0
    res = res[(res["date"] >= pd.to_datetime(start_date)) & (res["date"] <= pd.to_datetime(end_date))]
    res["factor"] = res["factor"].replace([np.inf, -np.inf], np.nan).astype("float64").fillna(0.0)
    return res[["date", "instrument", "factor"]].sort_values(["date", "instrument"]).reset_index(drop=True)


def _addon_s5_c_abnvol(datasources, start_date, end_date):
    """
    本段成交量相对同时段 20 日常态（对数）取负

    评分机批量筛选候选（s5）。共用分钟级统计 SQL（单次 GROUP BY，不用窗口函数），跨段运算在 pandas 中完成。
    最终：逐截面排名居中，按股票跨截面指数平滑 α=0.3（过去的权重），09:30 截面置 0，缺失补 0。只用过去数据。
    """
    import numpy as np
    import pandas as pd
    import dai

    bar1m = datasources["bar1m"]
    LOOKBACK_DAYS = 45
    query_start = (pd.to_datetime(start_date) - pd.Timedelta(days=LOOKBACK_DAYS)).strftime("%Y-%m-%d %H:%M:%S")
    sql = f"""
    WITH cte_raw AS (
        SELECT
            instrument_id,
            strftime(date, '%Y-%m-%d') AS trading_day,
            strftime(date, '%H%M%S') AS hms,
            CAST(open AS DOUBLE) AS o, CAST(high AS DOUBLE) AS h, CAST(low AS DOUBLE) AS l, CAST(close AS DOUBLE) AS c,
            CAST(COALESCE(volume, 0) AS DOUBLE) AS v, CAST(COALESCE(amount, 0) AS DOUBLE) AS a,
            CAST(COALESCE(deal_number, 0) AS DOUBLE) AS nd, CAST(pre_close AS DOUBLE) AS pc,
            CAST(bid_price1 AS DOUBLE) AS b1, CAST(ask_price1 AS DOUBLE) AS a1,
            CAST(bid_price2 AS DOUBLE) AS b2, CAST(ask_price2 AS DOUBLE) AS a2,
            CAST(bid_price3 AS DOUBLE) AS b3, CAST(ask_price3 AS DOUBLE) AS a3
        FROM {bar1m}
    ),
    cte_m AS (
        SELECT
            instrument_id, trading_day, hms, o, h, l, c, v, a, nd, pc,
            CASE
                WHEN hms > '090000' AND hms <= '093000' THEN 93000
                WHEN hms > '093000' AND hms <= '100000' THEN 100000
                WHEN hms > '100000' AND hms <= '103000' THEN 103000
                WHEN hms > '103000' AND hms <= '110000' THEN 110000
                WHEN hms > '110000' AND hms <= '113000' THEN 113000
                WHEN hms > '130000' AND hms <= '133000' THEN 133000
                WHEN hms > '133000' AND hms <= '140000' THEN 140000
                WHEN hms > '140000' AND hms <= '143000' THEN 143000
                WHEN hms > '143000' AND hms <= '150000' THEN 150000
                ELSE -1
            END AS seg,
            CASE WHEN o > 0 AND c > 0 AND v > 0 THEN ln(c / o) ELSE NULL END AS r,
            CASE WHEN h > l AND v > 0 AND o > 0 AND c > 0 THEN v * (c - o) / (h - l) ELSE 0 END AS sv,
            CASE WHEN b1 > 0 AND a1 > b1 THEN (a1 + b1) / 2.0 ELSE NULL END AS mid,
            CASE WHEN b1 > 0 AND a1 > b1 AND c > 0 THEN LEAST(GREATEST((c - b1) / (a1 - b1), 0.0), 1.0) ELSE NULL END AS tpos,
            CASE WHEN b1 > 0 AND a1 > b1 AND a2 > a1 AND b2 > 0 AND b2 < b1 THEN ((a2 - a1) - (b1 - b2)) / ((a1 + b1) / 2.0) ELSE NULL END AS gap12,
            CASE WHEN b1 > 0 AND a1 > b1 AND a3 > a1 AND b3 > 0 AND b3 < b1 THEN ((a3 - a1) - (b1 - b3)) / ((a1 + b1) / 2.0) ELSE NULL END AS gap13
        FROM cte_raw
    ),
    cte_seg AS (
        SELECT
            trading_day, seg, instrument_id,
            SUM(r) AS sr, SUM(r * r) AS sr2, SUM(r * r * r) AS sr3, SUM(r * r * r * r) AS sr4, SUM(ABS(r)) AS sabs,
            SUM(CASE WHEN r > 0 THEN r * r ELSE 0 END) AS sr2p, SUM(CASE WHEN r < 0 THEN r * r ELSE 0 END) AS sr2n,
            MAX(r) AS rmax, MIN(r) AS rmin, COUNT(r) AS nmin, SUM(CASE WHEN r = 0 THEN 1 ELSE 0 END) AS nzero,
            SUM(sv) AS ssv, SUM(COALESCE(r, 0) * sv) AS srsv, SUM(sv * sv) AS ssv2,
            SUM(CASE WHEN sv > 0 THEN COALESCE(r, 0) * sv ELSE 0 END) AS srsvp, SUM(CASE WHEN sv > 0 THEN sv * sv ELSE 0 END) AS ssv2p,
            SUM(CASE WHEN sv < 0 THEN COALESCE(r, 0) * sv ELSE 0 END) AS srsvn, SUM(CASE WHEN sv < 0 THEN sv * sv ELSE 0 END) AS ssv2n,
            SUM(CASE WHEN r > 0 THEN v ELSE 0 END) AS vup, SUM(CASE WHEN r < 0 THEN v ELSE 0 END) AS vdn,
            SUM(v) AS vol, SUM(a) AS amt, SUM(nd) AS ndeal,
            AVG(tpos) AS tpos, AVG(gap12) AS gap12, AVG(gap13) AS gap13,
            arg_min(CASE WHEN o > 0 THEN o ELSE NULL END, hms) AS s_open, MAX(CASE WHEN h > 0 THEN h ELSE NULL END) AS s_high,
            MIN(CASE WHEN l > 0 THEN l ELSE NULL END) AS s_low,
            arg_max(CASE WHEN mid > 0 THEN mid WHEN c > 0 THEN c ELSE NULL END, hms) AS last_px,
            arg_max(hms, CASE WHEN h > 0 THEN h ELSE NULL END) AS hms_high, arg_min(hms, CASE WHEN l > 0 THEN l ELSE NULL END) AS hms_low,
            MAX(pc) AS pre_close
        FROM cte_m
        WHERE seg != -1
        GROUP BY instrument_id, trading_day, seg
    )
    SELECT
        CAST(CONCAT(f.trading_day, ' ', strftime(strptime(LPAD(CAST(f.seg AS VARCHAR), 6, '0'), '%H%M%S'), '%H:%M:%S')) AS DATETIME) AS date,
        all_instruments.instrument, f.*
    FROM cte_seg f
    LEFT JOIN all_instruments USING (instrument_id)
"""
    df = dai.query(sql, filters={"date": [query_start, end_date]}, compression=True).df()
    df = df.dropna(subset=["instrument"]).drop_duplicates(["date", "instrument"])
    df["date"] = pd.to_datetime(df["date"])
    for c in df.columns:
        if c not in ("date", "instrument", "trading_day", "seg", "instrument_id", "hms_high", "hms_low"):
            df[c] = df[c].astype("float64")
    df = df.sort_values(["instrument", "date"]).reset_index(drop=True)
    df["day"] = df["date"].dt.normalize()
    inst = df["instrument"]
    g = df.groupby("instrument", sort=False)
    gd = df.groupby(["instrument", "day"], sort=False)

    def pos(x):
        return x.where(x > 0)

    def lr(a, b):
        return np.log(pos(a) / pos(b))

    def roll(col, k):
        x = df[col].fillna(0.0) if isinstance(col, str) else col.fillna(0.0)
        cs = x.groupby(inst).cumsum()
        return cs - cs.groupby(inst).shift(k).fillna(0.0)

    def tmin(hms):
        """时刻 → 开盘以来的交易分钟（午休不计）。"""
        t = pd.to_numeric(hms, errors="coerce")
        hh, mm = t // 10000, (t // 100) % 100
        m = hh * 60 + mm
        return np.where(m <= 690, m - 570, m - 660)

    px = pos(df["last_px"])
    prev = g["last_px"].shift(1)
    r_seg = lr(px, prev)
    day_open = gd["s_open"].transform("first")
    day_high = gd["s_high"].cummax()
    day_low = gd["s_low"].cummin()
    newh = df["s_high"] >= day_high
    newl = df["s_low"] <= day_low
    t_high = pd.Series(np.where(newh, tmin(df["hms_high"]), np.nan), index=df.index).groupby([inst, df["day"]]).ffill()
    t_low = pd.Series(np.where(newl, tmin(df["hms_low"]), np.nan), index=df.index).groupby([inst, df["day"]]).ffill()
    t_now = pd.Series(tmin(df["date"].dt.strftime("%H%M%S")), index=df.index)

    slot = df['date'].dt.strftime('%H%M')
    lv = np.log(pos(df['vol']))
    base = lv.groupby([inst, slot]).transform(lambda q: q.shift(1).rolling(20, min_periods=8).mean())
    abn = lv - base
    x = -abn

    x = pd.Series(np.asarray(x, dtype="float64"), index=df.index).replace([np.inf, -np.inf], np.nan)
    df["x"] = x
    instruments_table = datasources.get("instruments", "cpt_jyc_2026_instruments")
    pool = dai.query(f"SELECT date, instrument FROM {instruments_table}", filters={"date": [query_start, end_date]}, compression=True).df()
    pool["date"] = pd.to_datetime(pool["date"])
    res = pd.merge(pool, df[["date", "instrument", "x"]], how="left", on=["date", "instrument"]).drop_duplicates(["date", "instrument"])
    res["factor"] = res.groupby("date")["x"].rank(pct=True) - 0.5
    res["factor"] = res["factor"].fillna(0.0)
    hhmm = res["date"].dt.hour * 100 + res["date"].dt.minute
    res.loc[hhmm == 930, "factor"] = 0.0
    SMOOTH = 0.3
    if SMOOTH > 0:
        res = res.sort_values(["instrument", "date"])
        res["factor"] = res.groupby("instrument", sort=False)["factor"].transform(lambda q: q.ewm(alpha=1.0 - SMOOTH, adjust=False).mean())
        res.loc[hhmm.loc[res.index] == 930, "factor"] = 0.0
    res = res[(res["date"] >= pd.to_datetime(start_date)) & (res["date"] <= pd.to_datetime(end_date))]
    res["factor"] = res["factor"].replace([np.inf, -np.inf], np.nan).astype("float64").fillna(0.0)
    return res[["date", "instrument", "factor"]].sort_values(["date", "instrument"]).reset_index(drop=True)

_STYLES = ["SIZE", "BETA", "MOMENTUM", "RESVOL", "SIZENL", "BTOP", "LIQUIDTY", "EARNYILD", "GROWTH", "LEVERAGE"]


def _resid_styles(d, datasources, start_date, end_date):
    """d["z"] 逐截面对 10 个官方风格暴露 + 申万一级行业哑变量（含截距）做 OLS，返回残差（暴露缺失的股票原值不动）。
    暴露表第 t 天的值在当天收盘后才可得，一律取该股票前一交易日的值。09:30 截面跳过（之后置 0）。"""
    import numpy as np
    import pandas as pd
    import dai

    exposure_table = datasources.get("exposure", "cpt_jyc_2026_exposure")
    qs = (pd.to_datetime(start_date) - pd.Timedelta(days=20)).strftime("%Y-%m-%d %H:%M:%S")
    e = dai.query("SELECT date, instrument, %s, industry_level1_code FROM %s" % (", ".join(_STYLES), exposure_table),
                  filters={"date": [qs, end_date]}, compression=True).df()
    e["day"] = pd.to_datetime(e["date"]).dt.normalize()
    e["instrument"] = e["instrument"].astype(str)
    e = e.drop_duplicates(["instrument", "day"]).sort_values(["instrument", "day"]).reset_index(drop=True)
    ind = sorted(e["industry_level1_code"].dropna().astype(str).unique())
    X = pd.DataFrame({c: pd.to_numeric(e[c], errors="coerce").astype(float) for c in _STYLES})
    for c in ind:
        X["i_" + c] = (e["industry_level1_code"].astype(str) == c).astype(float)
    X[e["industry_level1_code"].isna().to_numpy()] = np.nan
    cols = list(X.columns)
    X["instrument"], X["day"] = e["instrument"].to_numpy(), e["day"].to_numpy()
    X[cols] = X.groupby("instrument")[cols].shift(1)                             # 前一交易日
    m = pd.DataFrame({"instrument": d["instrument"].to_numpy(), "day": d["date"].dt.normalize().to_numpy()}).merge(
        X, on=["instrument", "day"], how="left")
    A = m[cols].to_numpy(float)
    v = d["z"].to_numpy(float).copy()
    ok = np.isfinite(A).all(axis=1) & np.isfinite(v) & (d["date"].dt.strftime("%H%M") != "0930").to_numpy()
    out = v.copy()
    for _, idx in d.groupby("date", sort=False).indices.items():
        k = idx[ok[idx]]
        if len(k) < 50:
            continue
        Ak = np.column_stack([np.ones(len(k)), A[k]])
        b = np.linalg.lstsq(Ak, v[k], rcond=None)[0]
        out[k] = v[k] - Ak @ b
    return out


